from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    mark = max((value for value in counts if value != background), key=lambda value: counts[value])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == mark]
    out = [row[:] for row in grid]
    min_r = min(r for r, c in points)
    max_r = max(r for r, c in points)
    min_c = min(c for r, c in points)
    max_c = max(c for r, c in points)

    rows = {min_r, max_r}
    rows.update(r for r in range(min_r + 1, max_r)
                if sum(grid[r][c] == mark for c in range(min_c, max_c + 1)) >= 5)
    cols = {min_c, max_c}
    cols.update(c for c in range(min_c + 1, max_c)
                if sum(grid[r][c] == mark for r in range(min_r, max_r + 1)) >= 5)

    for r in rows:
        for c in range(min_c, max_c + 1):
            if out[r][c] == background:
                out[r][c] = 2
    for c in cols:
        for r in range(min_r, max_r + 1):
            if out[r][c] == background:
                out[r][c] = 2
    return out
